create table if not exists sourcecubes.setc_patent_landscape_evidence (
  setc_id text primary key,
  source_specification text not null,
  source_url text,
  preliminary_ip_treatment text,
  filing_priority text,
  filing_status text,
  legacy_49_eligibility text not null default 'REQUIRES_DEDUPLICATION_AND_COUNSEL_REVIEW',
  notes text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

values ('IP-EV-006','SETC_PATENT_LANDSCAPE','SETC Master Patent Landscape & Invention Capture Register — Version 1.0','Google Drive','1unKxBaCzRQ6Jg0RWhguUSyClmHjv2m1s','DOCUMENTED','OWNERSHIP_AND_INVENTORSHIP_REVIEW_REQUIRED','UNFILED',false,'SETC landscape is a preliminary invention-capture lane. It contains patent candidates, continuation/combination candidates, and trade-secret/copyright review items. Do not consume legacy 49 slots without deduplication against canonical IP families and counsel review.')
on conflict (evidence_id) do update set notes=excluded.notes, updated_at=now();

on conflict (setc_id) do update set source_specification=excluded.source_specification, source_url=excluded.source_url, preliminary_ip_treatment=excluded.preliminary_ip_treatment, filing_priority=excluded.filing_priority, filing_status=excluded.filing_status, notes=excluded.notes, updated_at=now();
